import java.util.Random;

/**
 * A class representing all shared characteristics of organisms.
 * Organisms have an age, field and a location in the field.
 * All organisms are able to act and breed.
 *
 * @version 2022.03.02
 */
public abstract class Organism
{
    // The organism's age
    private int age;
    // Whether the organism is alive or not.
    private boolean alive;
    // The organism's field.
    private Field field;
    // The organism's position in the field.
    private Location location;

    // A shared random number generator to control breeding.
    private static final Random rand = Randomizer.getRandom();

    /**
     * Constructor for objects of class Organism
     */
    public Organism(boolean randomAge, Field field, Location location)
    {
        age = 0;
        if (randomAge) {
            age = rand.nextInt(getMaxAge());
        }
        alive = true;
        this.field = field;
        setLocation(location);
    }

    // Abstract methods

    /**
     * Abstract method that returns whether the animal is diurnal or nocturnal
     * 
     * @return boolean True if the animal is diurnal, false if nocturnal
     */
    abstract protected boolean getIsDiurnal();

    /**
    * Make this organism act - that is: make it do
    * whatever it wants/needs to do.
    * @param newOrganisms A list to receive newly born organisms.
    */
    abstract public void act(List<Organism> newOrganisms);

    /**
     * Abstract method that returns the max age of the organism
     * 
     * @return the organism's max age
     */
    abstract protected int getMaxAge();

    /**
     * Abstract method that returns whether the organism can breed
     * 
     * @return boolean True if the organism can breed
     */
    abstract protected boolean canBreed();

    /**
     * Abstract method that returns the breeding age for the animal
     * 
     * @return the animal's breeding age
     */
    abstract protected int getBreedingAge();

    /**
     * Abstract methohd that returns the litter size of the animal
     * 
     * @return the animal's max litter size
     */
    abstract protected int getMaxLitterSize();

    /**
     * Abstract method that returns the breeding probability of the animal
     * 
     * @return the animal's breeding probability
     */
    abstract protected double getBreedingProbability();

    /**
     * Abstract method that returns an organism object of a specific subclass of organism
     * 
     * @return Organism object of a specified subclass
     */
    abstract protected Organism createNewOrganism(boolean randomAge, Field field, Location location);

    // Accessor and mutator methods

    /**
     * Return the organism's location.
     * @return The organism's location.
     */
    protected Location getLocation()
    {
        return location;
    }

    /**
     * Return the organism's field.
     * @return The organism's field.
     */
    protected Field getField()
    {
        return field;
    }

    /**
     * Returns the random object of the organism
     * 
     * @return Random object of the organism
     */
    protected Random getRand() {
        return rand;
    }

    /**
     * Returns the age of the organism
     * 
     * @return The organism's age
     */
    public int getAge()
    {
        return age;
    }

    /**
     * Sets the organism's age
     */
    protected void setAge(int age)
    {
        this.age = age;
    }

    /**
     * Check whether the organism is alive or not.
     * @return true if the organism is still alive.
     */
    public boolean isAlive()
    {
        return alive;
    }

    // Functional methods

    /**
     * Determines the amount of newborn a specific organism will produce
     * 
     * @return the number of newborn produced by the organism
     */
    protected int breed()
    {
        int births = 0;
        if(canBreed() && getRand().nextDouble() <= getBreedingProbability()) {
            births = getRand().nextInt(getMaxLitterSize()) + 1;
        }
        return births;
    }

    /**
     * Adds newborn organisms to a list
     */
    protected void giveBirth(List<Organism> newOrganisms)
    {
        // New rabbits are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int births = breed();
        for(int b = 0; b < births && free.size() > 0; b++) {
            Location loc = free.remove(0);
            Organism young = createNewOrganism(false, field, loc);
            newOrganisms.add(young);
        }
    }

    /**
     * Increases the age of the organism by one. If it goes over the max age, the organism dies.
     */
    protected void incrementAge()
    {
        age++;
        if (age > getMaxAge())
        {
            setDead();
        }
    }

    /**
     * Indicate that the organism is no longer alive.
     * It is removed from the field.
     */
    protected void setDead()
    {
        alive = false;
        if(location != null) {
            field.clear(location);
            location = null;
            field = null;
        }
    }

    /**
     * Place the organism at the new location in the given field.
     * @param newLocation The organism's new location.
     */
    protected void setLocation(Location newLocation)
    {
        if(location != null) {
            field.clear(location);
        }
        location = newLocation;
        field.place(this, newLocation);
    }
}

import java.util.List;
import java.util.Random;
import java.util.HashSet;
import java.util.Iterator;

/**
 * A model of a Sloth. Sloths will eat plants.
 * They will move and look for food and age at every step of the simulation,
 * and die when they reach their max age or have gone too long without food.
 * 
 * @version 2022.03.02
 */
public class Sloth extends Animal implements Infectable
{
    // Characteristics shared by all sloths (class variables).

    // The age at which a sloth can start to breed.
    private static final int BREEDING_AGE = 5;
    // The age to which a sloth can live.
    private static final int MAX_AGE = 30;
    // The likelihood of a sloth breeding.
    private static final double BREEDING_PROBABILITY = 0.17;
    // The maximum number of births.
    private static final int MAX_LITTER_SIZE = 4;
    // The max health of a sloth
    private static final int MAX_HEALTH = 8;
    // Whether the animal is diurnal or nocturnal
    private static final boolean IS_DIURNAL = true;

    // Individual characteristics (instance fields).
    // The food a sloth will eat.
    private static HashSet<Class> foodSources;
    // The classes a bear will kill
    private static HashSet<Class> killable;

    /**
     * Create a new sloth. A sloth may be created with age
     * zero (a new born) or with a random age.
     * 
     * @param randomAge If true, the sloth will have a random age.
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Sloth(boolean randomAge, Field field, Location location)
    {
        super(randomAge, field, location);
        foodSources = new HashSet<>();
        foodSources.add(Plant.class);

        killable = new HashSet<>();
        killable.add(Plant.class);
    }

    // Accessor and mutator methods
    /**
     * Return whether the sloth is diurnal
     * 
     * @return boolean True if the sloth is diurnal, false if nocturnal
     */
    protected boolean getIsDiurnal() {
        return IS_DIURNAL;
    }

    /**
     * Return the breeding age of the sloth
     * 
     * @return the sloth's breeding age
     */
    protected int getBreedingAge()
    {
        return BREEDING_AGE;
    }

    /**
     * Return the max age of the sloth
     * 
     * @return the sloth's max age
     */
    protected int getMaxAge()
    {
        return MAX_AGE;
    }

    /**
     * Return the breeding probability of the sloth
     * 
     * @return the sloth's breeding probability
     */
    protected double getBreedingProbability()
    {
        return BREEDING_PROBABILITY;
    }

    /**
     * Return the max litter size of the sloth
     * 
     * @return the sloth's max litter size
     */
    protected int getMaxLitterSize()
    {
        return MAX_LITTER_SIZE;
    }

    /**
     * Return the max health of the sloth
     * 
     * @return the sloth's max health
     */
    protected int getMaxHealth()
    {
        return MAX_HEALTH;
    }

    /**
     * Returns whether the target animal is of instance Sloth
     * 
     * @param target A target object that we want to check is of type Sloth
     * @return boolean True if target is of type Sloth
     */
    protected boolean getAnimalClass(Object target)
    {
        return target instanceof Sloth;
    }

    /**
     * Returns the HashSet of allowed food for a sloth to eat
     * 
     * @return HashSet<Class> of subclasses that a Sloth can eat
     */
    protected HashSet<Class> getFoodSources() {
        return foodSources;
    }

    /**
     * Returns the HashSet of allowed classes for a sloth to eat
     * 
     * @return HashSet<Class> of subclasses that a sloth can kill
     */
    protected HashSet<Class> getKillable() {
        return killable;
    }

    // Functional methods

    /**
     * This is what the sloth does most of the time - it runs 
     * around. Sometimes it will breed or die of old age.
     * @param newsloths A list to return newly born sloths.
     */
    public void act(List<Organism> newsloths)
    {
        incrementAge();
        incrementHealth();
        if (isAlive()) {
            illness();
        }
        if(isAlive()) {
            spreadDisease();
            giveBirth(newsloths);            
            // Try to move into a free location.
            Location newLocation = findFood();
            if(newLocation == null) { 
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }

            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

    /**
     * Decides whether this animal will infect another eligible animal.
     */
    public void spreadDisease() {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object object = field.getObjectAt(where);
            if (object != null) {
                Organism organism = (Organism) object;
                if (organism instanceof Infectable && organism.isAlive() && getRand().nextDouble() <= SPREAD_PROBABILITY ) {
                    Animal target = (Animal) organism;
                    target.infect();
                }
            }
        }
    }

    /**
     * Creates a new Animal object for a newborn sloth
     * 
     * @return an Animal object for a newborn sloth
     */
    protected Animal createNewOrganism(boolean randomAge, Field field, Location location)
    {
        return new Sloth(randomAge, field, location);
    }

    /**
     * Makes the sloth take extra damage if it is infected
     */
    public void illness() {
        if (getIsInfected()) {
            incrementHealth();
        }
    }
}

import java.util.Iterator;
import java.util.List;
import java.util.ArrayList;

/**
 * The Infectable interface specifies the methods that an
 * animal who is able to be infected and is able to spread
 * infections must implement.
 *
 * @version 2022.03.02
 */
public interface Infectable
{
    // Probability of spreading disease
    public double SPREAD_PROBABILITY = 0.1;

    /**
     * Decides whether the animal will spread their disease to another animal.
     */
    void spreadDisease();

    /**
     * If an animal is infected, reduce its health.
     */
    void illness();
}

import java.util.Random;
import java.util.List;
import java.util.ArrayList;
import java.util.Iterator;
import java.awt.Color;

/**
 * A simple predator-prey simulator, based on a rectangular field
 * containing rabbits and foxes.
 * 
 * @version 2022.03.02
 */
public class Simulator
{
    // Constants representing configuration information for the simulation.
    // The default width for the grid.
    private static final int DEFAULT_WIDTH = 120;
    // The default depth of the grid.
    private static final int DEFAULT_DEPTH = 80;
    // The probability that a rabbit will be created in any given grid position.
    private static final double HIPPOPOTAMUS_CREATION_PROBABILITY = 0.01;
    // The probability that a rabbit will be created in any given grid position.
    private static final double LEOPARD_CREATION_PROBABILITY = 0.03; 
    // The probability that a rabbit will be created in any given grid position.
    private static final double BEAR_CREATION_PROBABILITY = 0.03; 
    // The probability that a rabbit will be created in any given grid position.
    private static final double MONKEY_CREATION_PROBABILITY = 0.08; 
    // The probability that a rabbit will be created in any given grid position.
    private static final double SLOTH_CREATION_PROBABILITY = 0.08; 
    // The probability that a plant will be created in any given grid position.
    private static final double PLANT_CREATION_PROBABILITY = 0.13;
    // A shared Weather object between organisms and the simulator
    public static final Weather weather = Weather.getWeather();


    // List of animals in the field.
    private List<Organism> organisms;
    // The current state of the field.
    private Field field;
    // The current step of the simulation.
    private int step;
    // A graphical view of the simulation.
    private SimulatorView view;

    /**
     * Construct a simulation field with default size.
     */
    public Simulator()
    {
        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
    }

    /**
     * Create a simulation field with the given size.
     * @param depth Depth of the field. Must be greater than zero.
     * @param width Width of the field. Must be greater than zero.
     */
    public Simulator(int depth, int width)
    {
        if(width <= 0 || depth <= 0) {
            System.out.println("The dimensions must be greater than zero.");
            System.out.println("Using default values.");
            depth = DEFAULT_DEPTH;
            width = DEFAULT_WIDTH;
        }

        organisms = new ArrayList<>();
        field = new Field(depth, width);

        // Create a view of the state of each location in the field.
        view = new SimulatorView(depth, width, step);
        view.setColor(Hippopotamus.class, Color.DARK_GRAY);
        view.setColor(Leopard.class, Color.MAGENTA);
        view.setColor(Bear.class, Color.RED);
        view.setColor(Monkey.class, Color.ORANGE);
        view.setColor(Sloth.class, Color.YELLOW);        
        view.setColor(Plant.class, Color.GREEN);

        // Setup a valid starting point.
        reset();
    }

    // Accessor and mutator methods

    /**
     * Return the current step number of the simulation
     * 
     * @return int of the current step in the simulation
     */
    public int getStepNumber()
    {
        return step;
    }

    // Functional methods

    /**
     * Run the simulation from its current state for a reasonably long period,
     * (4000 steps).
     */
    public void runLongSimulation()
    {
        simulate(4000);
    }

    /**
     * Run the simulation from its current state for the given number of steps.
     * Stop before the given number of steps if it ceases to be viable.
     * @param numSteps The number of steps to run for.
     */
    public void simulate(int numSteps)
    {
        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
            simulateOneStep();
            //delay(60);   // uncomment this to run more slowly
        }
    }

    /**
     * Run the simulation from its current state for a single step.
     * Iterate over the whole field updating the state of each
     * fox and rabbit.
     */
    public void simulateOneStep()
    {
        step++;
        randomWeather();
        // Provide space for newborn animals.
        List<Organism> newOrganisms = new ArrayList<>();        
        // Let all rabbits act.
        for(Iterator<Organism> it = organisms.iterator(); it.hasNext(); ) {
            Organism organism = it.next();

            if (organism.getIsDiurnal() && step % 80 <= 55) {
                organism.act(newOrganisms);
            }
            else if (!organism.getIsDiurnal() && step % 80 > 55) {
                organism.act(newOrganisms);
            }
            if(! organism.isAlive()) {
                it.remove();
            }
        }

        // Add the newly born organisms to the main lists.
        organisms.addAll(newOrganisms);
        view.showStatus(step, field);
    }

    /**
     * Reset the simulation to a starting position.
     */
    public void reset()
    {
        step = 0;
        organisms.clear();
        populate();
        weather.resetWeather();

        // Show the starting state in the view.
        view.showStatus(step, field);
    }

    /**
     * Randomly populate the field with foxes and rabbits.
     */
    private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                if(rand.nextDouble() <= HIPPOPOTAMUS_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Hippopotamus hippopotamus = new Hippopotamus(true, field, location);
                    organisms.add(hippopotamus);
                }
                else if(rand.nextDouble() <= LEOPARD_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Leopard leopard = new Leopard(true, field, location);
                    organisms.add(leopard);
                }
                else if(rand.nextDouble() <= BEAR_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Bear bear = new Bear(true, field, location);
                    organisms.add(bear);
                }
                else if(rand.nextDouble() <= MONKEY_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Monkey monkey = new Monkey(true, field, location);
                    organisms.add(monkey);
                }
                if(rand.nextDouble() <= SLOTH_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Sloth sloth = new Sloth(true, field, location);
                    organisms.add(sloth);
                }
                else if (rand.nextDouble() <= PLANT_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Plant plant = new Plant(true, field, location);
                    organisms.add(plant);
                }
                // else leave the location empty.
            }
        }
    }

    /**
     * Pause for a given time.
     * @param millisec  The time to pause for, in milliseconds
     */
    private void delay(int millisec)
    {
        try {
            Thread.sleep(millisec);
        }
        catch (InterruptedException ie) {
            // wake up
        }
    }

    /**
     * Randomises the weather
     */
    public void randomWeather() {
        if (step % 450 == 0) {
            weather.changeWeather();
        }
    }
}

import java.util.List;
import java.util.Random;
import java.util.Iterator;

/**
 * Write a description of class Plant here.
 *
 * @version (a version number or a date)
 */

public class Plant extends Organism
{
    // The age at which a monkey can start to breed.
    private static final int BREEDING_AGE = 5;
    // The age to which a monkey can live.
    private static final int MAX_AGE = 15;
    // The likelihood of a monkey breeding.
    private static final double BREEDING_PROBABILITY = 0.09;
    // The maximum number of births.
    private static final int MAX_LITTER_SIZE = 6;
    // Whether the animal is diurnal or nocturnal
    private static final boolean IS_DIURNAL = true;
    // A shared random number generator to control breeding.
    private static final Random rand = Randomizer.getRandom();

    public Plant(boolean randomAge, Field field, Location location)
    {
        super(randomAge, field, location);
    }

    // Accessor and mutator methods

    /**
     * Return whether the plant is diurnal
     * 
     * @return boolean True if the plant is diurnal, false if nocturnal
     */
    protected boolean getIsDiurnal() {
        return IS_DIURNAL;
    }

    public void act(List<Organism> newOrganisms) {
        incrementAge();
        if(isAlive()) {
            giveBirth(newOrganisms);
        }
    }

    /**
     * Returns breeding age of a plant
     * 
     * @return int of the plant's breeding age.
     */
    protected int getBreedingAge() {
        return BREEDING_AGE;
    }

    /**
     * Returns max age of a plant
     * 
     * @return int of the plant's max age.
     */
    protected int getMaxAge() {
        return MAX_AGE;
    }

    /**
     * Returns whether the plant can breed, if it is above the breeding age
     * 
     * @return boolean True if the plant can breed
     */
    protected boolean canBreed() {
        return getAge() >= BREEDING_AGE;
    }

    /**
     * Returns max litter size of a plant
     * 
     * @return int of the plant's max litter size
     */
    protected int getMaxLitterSize() {
        return MAX_LITTER_SIZE;
    }

    /**
     * Returns breeding probability of a plant
     * 
     * @return double of the plant's breeding probability
     */
    protected double getBreedingProbability() {
        return BREEDING_PROBABILITY;
    }

    // Functional methods

    /**
     * Creates and returns a new plant object
     * 
     * @return Organism object of subclass plant
     */
    protected Organism createNewOrganism(boolean randomAge, Field field, Location location) {
        return new Plant(randomAge, field, location);
    }
}

import java.util.Collections;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import java.util.Random;

/**
 * Represent a rectangular grid of field positions.
 * Each position is able to store a single animal.
 *
 * @version 2016.02.29
 */
public class Field
{
    // A random number generator for providing random locations.
    private static final Random rand = Randomizer.getRandom();

    // The depth and width of the field.
    private int depth, width;
    // Storage for the animals.
    private Object[][] field;

    /**
     * Represent a field of the given dimensions.
     * @param depth The depth of the field.
     * @param width The width of the field.
     */
    public Field(int depth, int width)
    {
        this.depth = depth;
        this.width = width;
        field = new Object[depth][width];
    }

    /**
     * Empty the field.
     */
    public void clear()
    {
        for(int row = 0; row < depth; row++) {
            for(int col = 0; col < width; col++) {
                field[row][col] = null;
            }
        }
    }

    /**
     * Clear the given location.
     * @param location The location to clear.
     */
    public void clear(Location location)
    {
        field[location.getRow()][location.getCol()] = null;
    }

    /**
     * Place an animal at the given location.
     * If there is already an animal at the location it will
     * be lost.
     * @param animal The animal to be placed.
     * @param row Row coordinate of the location.
     * @param col Column coordinate of the location.
     */
    public void place(Object animal, int row, int col)
    {
        place(animal, new Location(row, col));
    }

    /**
     * Place an animal at the given location.
     * If there is already an animal at the location it will
     * be lost.
     * @param animal The animal to be placed.
     * @param location Where to place the animal.
     */
    public void place(Object animal, Location location)
    {
        field[location.getRow()][location.getCol()] = animal;
    }

    /**
     * Return the animal at the given location, if any.
     * @param location Where in the field.
     * @return The animal at the given location, or null if there is none.
     */
    public Object getObjectAt(Location location)
    {
        return getObjectAt(location.getRow(), location.getCol());
    }

    /**
     * Return the animal at the given location, if any.
     * @param row The desired row.
     * @param col The desired column.
     * @return The animal at the given location, or null if there is none.
     */
    public Object getObjectAt(int row, int col)
    {
        return field[row][col];
    }

    /**
     * Generate a random location that is adjacent to the
     * given location, or is the same location.
     * The returned location will be within the valid bounds
     * of the field.
     * @param location The location from which to generate an adjacency.
     * @return A valid location within the grid area.
     */
    public Location randomAdjacentLocation(Location location)
    {
        List<Location> adjacent = adjacentLocations(location);
        return adjacent.get(0);
    }

    /**
     * Get a shuffled list of the free adjacent locations.
     * @param location Get locations adjacent to this.
     * @return A list of free adjacent locations.
     */
    public List<Location> getFreeAdjacentLocations(Location location)
    {
        List<Location> free = new LinkedList<>();
        List<Location> adjacent = adjacentLocations(location);
        for(Location next : adjacent) {
            if(getObjectAt(next) == null) {
                free.add(next);
            }
        }
        return free;
    }

    /**
     * Try to find a free location that is adjacent to the
     * given location. If there is none, return null.
     * The returned location will be within the valid bounds
     * of the field.
     * @param location The location from which to generate an adjacency.
     * @return A valid location within the grid area.
     */
    public Location freeAdjacentLocation(Location location)
    {
        // The available free ones.
        List<Location> free = getFreeAdjacentLocations(location);
        if(free.size() > 0) {
            return free.get(0);
        }
        else {
            return null;
        }
    }

    /**
     * Return a shuffled list of locations adjacent to the given one.
     * The list will not include the location itself.
     * All locations will lie within the grid.
     * @param location The location from which to generate adjacencies.
     * @return A list of locations adjacent to that given.
     */
    public List<Location> adjacentLocations(Location location)
    {
        assert location != null : "Null location passed to adjacentLocations";
        // The list of locations to be returned.
        List<Location> locations = new LinkedList<>();
        if(location != null) {
            int row = location.getRow();
            int col = location.getCol();
            for(int roffset = -1; roffset <= 1; roffset++) {
                int nextRow = row + roffset;
                if(nextRow >= 0 && nextRow < depth) {
                    for(int coffset = -1; coffset <= 1; coffset++) {
                        int nextCol = col + coffset;
                        // Exclude invalid locations and the original location.
                        if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
                            locations.add(new Location(nextRow, nextCol));
                        }
                    }
                }
            }

            // Shuffle the list. Several other methods rely on the list
            // being in a random order.
            Collections.shuffle(locations, rand);
        }
        return locations;
    }

    /**
     * Return the depth of the field.
     * @return The depth of the field.
     */
    public int getDepth()
    {
        return depth;
    }

    /**
     * Return the width of the field.
     * @return The width of the field.
     */
    public int getWidth()
    {
        return width;
    }
}

