import java.util.Iterator;
import java.util.List;

/**
 * Shared behavior for animals that can spread and receive infections.
 */
public abstract class InfectableAnimal extends Animal implements Infectable
{
    /**
     * Create a new infectable animal at a location in the field.
     *
     * @param randomAge If true, the animal will have a random age and hunger level.
     * @param field The field currently occupied.
     * @param location The location within the field.
     * @param breedingAge The breeding age.
     * @param maxAge The maximum age.
     * @param breedingProbability The breeding probability.
     * @param maxLitterSize The maximum litter size.
     * @param isDiurnal Whether the animal is diurnal.
     * @param maxHealth The maximum health.
     * @param animalClass The concrete species type.
     * @param foodSources The food sources available to the species.
     * @param killable The classes this species can kill.
     */
    protected InfectableAnimal(boolean randomAge, Field field, Location location,
            int breedingAge, int maxAge, double breedingProbability,
            int maxLitterSize, boolean isDiurnal, int maxHealth,
            Class<? extends Animal> animalClass, java.util.HashSet<Class> foodSources,
            java.util.HashSet<Class> killable)
    {
        super(randomAge, field, location, breedingAge, maxAge, breedingProbability,
                maxLitterSize, isDiurnal, maxHealth, animalClass, foodSources, killable);
    }

    /**
     * Decides whether this animal will infect another eligible animal.
     */
    public void spreadDisease() {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object object = field.getObjectAt(where);
            if (object != null) {
                Organism organism = (Organism) object;
                if (organism instanceof Infectable && organism.isAlive() && getRand().nextDouble() <= SPREAD_PROBABILITY ) {
                    Animal target = (Animal) organism;
                    target.infect();
                }
            }
        }
    }

    /**
     * Makes the animal take extra damage if it is infected.
     */
    public void illness() {
        if (getIsInfected()) {
            incrementHealth();
        }
    }

    /**
     * Performs the infection-specific portion of a turn.
     *
     * @param newOrganisms A list to receive newborn animals.
     */
    protected void performInfectableAct(List<Organism> newOrganisms)
    {
        illness();
        if (isAlive()) {
            spreadDisease();
            performStandardAct(newOrganisms);
        }
    }
}

import java.util.List;
import java.util.Iterator;
import java.util.HashSet;

/**
 * A class representing shared characteristics of all animals within the simultion.
 * Animals will find food, have a gender and be able to become infected.
 * 
 * @version 2022.03.02
 */
public abstract class Animal extends Organism
{
    // A singleton shared weather object between all organisms and the simulator
    private static final Weather weather = Weather.getWeather();
    // The concrete species this animal instance belongs to.
    private final Class<? extends Animal> animalClass;
    // The animal's maximum health.
    private final int maxHealth;
    // Gender of the animal
    private boolean isMale;
    // Current health of the animal
    private int currentHealth;
    // Whether the animal is infected
    private boolean isInfected;
    // The food sources available to this animal.
    private final HashSet<Class> foodSources;
    // The classes this animal is willing to kill.
    private final HashSet<Class> killable;

    /**
     * Create a new animal at location in field.
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Animal(boolean randomAge, Field field, Location location,
            int breedingAge, int maxAge, double breedingProbability,
            int maxLitterSize, boolean isDiurnal, int maxHealth,
            Class<? extends Animal> animalClass, HashSet<Class> foodSources,
            HashSet<Class> killable)
    {
        super(randomAge, field, location, breedingAge, maxAge, breedingProbability,
                maxLitterSize, isDiurnal);
        this.maxHealth = maxHealth;
        this.animalClass = animalClass;
        this.foodSources = new HashSet<>(foodSources);
        this.killable = new HashSet<>(killable);

        if (randomAge) {
            currentHealth = getRand().nextInt(maxHealth);
        }
        if (getRand().nextInt(2) == 0) {
            isMale = true;
        }
        else {
            isMale = false;
        }

        isInfected = false;
    }

    // Accessor and mutator methods

    /**
     * Returns whether the animal is male
     * 
     * @boolean True if the animal is male, false if animal is female
     */
    protected boolean getGender()
    {
        return isMale;
    }

    /**
     * Return the current health of the animal
     * 
     * @return int of the animal's current health
     */
    protected int getCurrentHealth() {
        return currentHealth;
    }

    /**
     * Return whether the animal is infected
     * 
     * @return True if the animal is infected, false if not
     */
    protected boolean getIsInfected() {
        return isInfected;
    }

    /**
     * Returns the animal's max health.
     *
     * @return the animal's max health.
     */
    protected int getMaxHealth()
    {
        return maxHealth;
    }

    /**
     * Returns whether the supplied object is the same species as this animal.
     *
     * @param thing The object being compared.
     * @return True if the object is of this animal's species.
     */
    protected boolean getAnimalClass(Object thing)
    {
        return animalClass.isInstance(thing);
    }

    /**
     * Returns the food sources available to this animal.
     *
     * @return The animal's food sources.
     */
    protected HashSet<Class> getFoodSources() {
        return foodSources;
    }

    /**
     * Returns the classes this animal can kill.
     *
     * @return The animal's killable classes.
     */
    protected HashSet<Class> getKillable() {
        return killable;
    }

    /**
     * Sets the animal to infected state
     */
    protected void infect() {
        isInfected = true;
    }

    // Functional methods

    /**
     * Checks if the animal can breed
     * 
     * @return true if the animal can breed
     */
    protected boolean canBreed()
    {
        if (isMale == false)
        {
            Field field = getField();
            List<Location> adjacent = field.adjacentLocations(getLocation());
            Iterator<Location> it = adjacent.iterator();
            while (it.hasNext())
            {
                Location where = it.next();
                Object thing = field.getObjectAt(where);
                if (getAnimalClass(thing))
                {
                    Animal animal = (Animal) thing;
                    return animal.getGender() == true && getAge() >= getBreedingAge();
                }
            }
        }
        return false;
    }

    /**
     * Handles the standard post-survival behavior shared by most animals.
     *
     * @param newOrganisms A list to receive newborn animals.
     */
    protected void performStandardAct(List<Organism> newOrganisms)
    {
        giveBirth(newOrganisms);
        Location newLocation = findFood();
        if(newLocation == null) { 
            newLocation = getField().freeAdjacentLocation(getLocation());
        }
        if(newLocation != null) {
            setLocation(newLocation);
        }
        else {
            setDead();
        }
    }

    /**
     * A method that will make the animal object search the adjacent squares around it,
     * then find and eat an eligible food source.
     */
    protected Location findFood() {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();
        while(it.hasNext()) {
            Location where = it.next();
            Object animal = field.getObjectAt(where);
            if (animal != null) {                       // makes sure to filter out empty squares
                Organism target = (Organism) animal;
                if (this.getFoodSources().contains(target.getClass()) && target.isAlive() && getRand().nextDouble() <= weather.getWeatherModifier()) {
                    target.setDead();
                    //currentHealth = this.getMaxHealth();
                    if (this.getFoodSources().contains(target.getClass())) {
                        currentHealth = this.getMaxHealth();
                    }
                }
            }
        }
        return null;
    }

    /**
     * Decrease this animal's. This could result in the animal's death by hunger.
     */
    protected void incrementHealth()
    {
        currentHealth--;
        if(currentHealth == 0) {
            setDead();
        }
    }

    /**
     * Helper for species constructors to create a set of classes.
     *
     * @param classes The classes to include.
     * @return A HashSet containing the supplied classes.
     */
    protected static HashSet<Class> classSet(Class... classes)
    {
        HashSet<Class> set = new HashSet<>();
        for(Class clazz : classes) {
            set.add(clazz);
        }
        return set;
    }
}

import java.util.List;
import java.util.Random;

/**
 * A class representing all shared characteristics of organisms.
 * Organisms have an age, field and a location in the field.
 * All organisms are able to act and breed.
 *
 * @version 2022.03.02
 */
public abstract class Organism
{
    // The organism's age
    private int age;
    // Whether the organism is alive or not.
    private boolean alive;
    // The organism's field.
    private Field field;
    // The organism's position in the field.
    private Location location;
    // Species-specific lifecycle characteristics.
    private final int breedingAge;
    private final int maxAge;
    private final double breedingProbability;
    private final int maxLitterSize;
    private final boolean isDiurnal;

    // A shared random number generator to control breeding.
    private static final Random rand = Randomizer.getRandom();

    /**
     * Constructor for objects of class Organism
     */
    public Organism(boolean randomAge, Field field, Location location,
            int breedingAge, int maxAge, double breedingProbability,
            int maxLitterSize, boolean isDiurnal)
    {
        age = 0;
        if (randomAge) {
            age = rand.nextInt(maxAge);
        }
        alive = true;
        this.field = field;
        this.breedingAge = breedingAge;
        this.maxAge = maxAge;
        this.breedingProbability = breedingProbability;
        this.maxLitterSize = maxLitterSize;
        this.isDiurnal = isDiurnal;
        setLocation(location);
    }

    // Abstract methods

    /**
    * Make this organism act - that is: make it do
    * whatever it wants/needs to do.
    * @param newOrganisms A list to receive newly born organisms.
    */
    abstract public void act(List<Organism> newOrganisms);

    /**
     * Abstract method that returns the max age of the organism
     * 
     * @return the organism's max age
     */
    /**
     * Abstract method that returns an organism object of a specific subclass of organism
     * 
     * @return Organism object of a specified subclass
     */
    abstract protected Organism createNewOrganism(boolean randomAge, Field field, Location location);

    // Accessor and mutator methods

    /**
     * Return the organism's location.
     * @return The organism's location.
     */
    protected Location getLocation()
    {
        return location;
    }

    /**
     * Return the organism's field.
     * @return The organism's field.
     */
    protected Field getField()
    {
        return field;
    }

    /**
     * Returns the random object of the organism
     * 
     * @return Random object of the organism
     */
    protected Random getRand() {
        return rand;
    }

    /**
     * Returns whether the organism is diurnal.
     *
     * @return True if the organism is diurnal, false if nocturnal.
     */
    protected boolean getIsDiurnal() {
        return isDiurnal;
    }

    /**
     * Returns the age of the organism
     * 
     * @return The organism's age
     */
    public int getAge()
    {
        return age;
    }

    /**
     * Sets the organism's age
     */
    protected void setAge(int age)
    {
        this.age = age;
    }

    /**
     * Returns the breeding age for the organism.
     *
     * @return the breeding age.
     */
    protected int getBreedingAge()
    {
        return breedingAge;
    }

    /**
     * Returns the max age for the organism.
     *
     * @return the max age.
     */
    protected int getMaxAge()
    {
        return maxAge;
    }

    /**
     * Returns the breeding probability for the organism.
     *
     * @return the breeding probability.
     */
    protected double getBreedingProbability()
    {
        return breedingProbability;
    }

    /**
     * Returns the maximum litter size for the organism.
     *
     * @return the maximum litter size.
     */
    protected int getMaxLitterSize()
    {
        return maxLitterSize;
    }

    /**
     * Check whether the organism is alive or not.
     * @return true if the organism is still alive.
     */
    public boolean isAlive()
    {
        return alive;
    }

    // Functional methods

    /**
     * Determines the amount of newborn a specific organism will produce
     * 
     * @return the number of newborn produced by the organism
     */
    protected int breed()
    {
        int births = 0;
        if(canBreed() && getRand().nextDouble() <= getBreedingProbability()) {
            births = getRand().nextInt(getMaxLitterSize()) + 1;
        }
        return births;
    }

    /**
     * Adds newborn organisms to a list
     */
    protected void giveBirth(List<Organism> newOrganisms)
    {
        // New rabbits are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int births = breed();
        for(int b = 0; b < births && free.size() > 0; b++) {
            Location loc = free.remove(0);
            Organism young = createNewOrganism(false, field, loc);
            newOrganisms.add(young);
        }
    }

    /**
     * Increases the age of the organism by one. If it goes over the max age, the organism dies.
     */
    protected void incrementAge()
    {
        age++;
        if (age > getMaxAge())
        {
            setDead();
        }
    }

    /**
     * Indicate that the organism is no longer alive.
     * It is removed from the field.
     */
    protected void setDead()
    {
        alive = false;
        if(location != null) {
            field.clear(location);
            location = null;
            field = null;
        }
    }

    /**
     * Place the organism at the new location in the given field.
     * @param newLocation The organism's new location.
     */
    protected void setLocation(Location newLocation)
    {
        if(location != null) {
            field.clear(location);
        }
        location = newLocation;
        field.place(this, newLocation);
    }
}

