141	     * Checks if the animal can breed
142	     * 
143	     * @return true if the animal can breed
144	     */
145	    protected boolean canBreed()
146	    {
147	        if (isMale == false)
148	        {
149	            Field field = getField();
150	            List<Location> adjacent = field.adjacentLocations(getLocation());
151	            Iterator<Location> it = adjacent.iterator();
152	            while (it.hasNext())
153	            {
154	                Location where = it.next();
155	                Object thing = field.getObjectAt(where);
156	                if (getAnimalClass(thing))
157	                {
158	                    Animal animal = (Animal) thing;
159	                    return animal.getGender() == true && getAge() >= getBreedingAge();
160	                }
161	            }
162	        }
163	        return false;
164	    }
