166	    /**
167	     * Handles the standard post-survival behavior shared by most animals.
168	     *
169	     * @param newOrganisms A list to receive newborn animals.
170	     */
171	    protected void performStandardAct(List<Organism> newOrganisms)
172	    {
173	        giveBirth(newOrganisms);
174	        Location newLocation = findFood();
175	        if(newLocation == null) { 
176	            newLocation = getField().freeAdjacentLocation(getLocation());
177	        }
178	        if(newLocation != null) {
179	            setLocation(newLocation);
180	        }
181	        else {
182	            setDead();
183	        }
184	    }
