186	    /**
187	     * A method that will make the animal object search the adjacent squares around it,
188	     * then find and eat an eligible food source.
189	     */
190	    protected Location findFood() {
191	        Field field = getField();
192	        List<Location> adjacent = field.adjacentLocations(getLocation());
193	        Iterator<Location> it = adjacent.iterator();
194	        while(it.hasNext()) {
195	            Location where = it.next();
196	            Object animal = field.getObjectAt(where);
197	            if (animal != null) {                       // makes sure to filter out empty squares
198	                Organism target = (Organism) animal;
199	                if (this.getFoodSources().contains(target.getClass()) && target.isAlive() && getRand().nextDouble() <= weather.getWeatherModifier()) {
200	                    target.setDead();
201	                    //currentHealth = this.getMaxHealth();
202	                    if (this.getFoodSources().contains(target.getClass())) {
203	                        currentHealth = this.getMaxHealth();
204	                    }
205	                }
206	            }
207	        }
208	        return null;
209	    }
210	    
211	    /**
212	     * Decrease this animal's. This could result in the animal's death by hunger.
213	     */
214	    protected void incrementHealth()
215	    {
216	        currentHealth--;
217	        if(currentHealth == 0) {
218	            setDead();
219	        }
220	    }
