222	    /**
223	     * Helper for species constructors to create a set of classes.
224	     *
225	     * @param classes The classes to include.
226	     * @return A HashSet containing the supplied classes.
227	     */
228	    protected static HashSet<Class> classSet(Class... classes)
229	    {
230	        HashSet<Class> set = new HashSet<>();
231	        for(Class clazz : classes) {
232	            set.add(clazz);
233	        }
234	        return set;
235	    }
