 7	public abstract class InfectableAnimal extends Animal implements Infectable
 8	{
 9	    /**
10	     * Create a new infectable animal at a location in the field.
11	     *
12	     * @param randomAge If true, the animal will have a random age and hunger level.
13	     * @param field The field currently occupied.
