16	     * @param maxAge The maximum age.
17	     * @param breedingProbability The breeding probability.
18	     * @param maxLitterSize The maximum litter size.
19	     * @param isDiurnal Whether the animal is diurnal.
20	     * @param maxHealth The maximum health.
21	     * @param animalClass The concrete species type.
22	     * @param foodSources The food sources available to the species.
23	     * @param killable The classes this species can kill.
24	     */
25	    protected InfectableAnimal(boolean randomAge, Field field, Location location,
26	            int breedingAge, int maxAge, double breedingProbability,
27	            int maxLitterSize, boolean isDiurnal, int maxHealth,
28	            Class<? extends Animal> animalClass, java.util.HashSet<Class> foodSources,
29	            java.util.HashSet<Class> killable)
30	    {
31	        super(randomAge, field, location, breedingAge, maxAge, breedingProbability,
32	                maxLitterSize, isDiurnal, maxHealth, animalClass, foodSources, killable);
33	    }
34	
35	    /**
36	     * Decides whether this animal will infect another eligible animal.
37	     */
38	    public void spreadDisease() {
39	        Field field = getField();
40	        List<Location> adjacent = field.adjacentLocations(getLocation());
41	        Iterator<Location> it = adjacent.iterator();
42	        while(it.hasNext()) {
43	            Location where = it.next();
44	            Object object = field.getObjectAt(where);
45	            if (object != null) {
46	                Organism organism = (Organism) object;
47	                if (organism instanceof Infectable && organism.isAlive() && getRand().nextDouble() <= SPREAD_PROBABILITY ) {
48	                    Animal target = (Animal) organism;
49	                    target.infect();
50	                }
51	            }
52	        }
53	    }
54	    
55	    /**
56	     * Makes the animal take extra damage if it is infected.
57	     */
58	    public void illness() {
59	        if (getIsInfected()) {
60	            incrementHealth();
61	        }
62	    }
