64	    /**
65	     * Performs the infection-specific portion of a turn.
66	     *
67	     * @param newOrganisms A list to receive newborn animals.
68	     */
69	    protected void performInfectableAct(List<Organism> newOrganisms)
70	    {
71	        illness();
72	        if (isAlive()) {
73	            spreadDisease();
74	            performStandardAct(newOrganisms);
75	        }
